package com.example.demo.repository;

import com.example.demo.model.User;
import org.springframework.data.mongodb.repository.MongoRepository;
import org.springframework.data.mongodb.repository.Query;
import org.springframework.stereotype.Repository;
import java.util.List;

@Repository
public interface UserRepository extends MongoRepository<User, String> {

    // Derived query method
    List<User> findByStatusAndAgeGreaterThan(String status, int age);

    // Explicit JSON-based query annotation with projection
    @Query(value = "{ 'status' : ?0 }", fields = "{ 'username' : 1, 'email' : 1 }")
    List<User> findSummaryByStatus(String status);
}
